parameters.jsCode:
const trig = $('1. Webhook Trigger').first().json.body || {};
let cand = {};
try {
  const res = $('3. Fetch Candidate Context API').first().json;
  cand = res.candidate || res.data || {};
} catch(e) {}

const isRejection = Boolean(
  trig.notification_type === 'rejection' ||
  cand.status === 'Loại' ||
  cand.status === 'Không đạt' ||
  cand.approval_status === 'REJECTED'
);

return [{
  json: {
    candidate_id: cand.id || trig.candidate_id,
    candidate_name: trig.candidate_name || cand.full_name || cand.name || "Ứng viên",
    candidate_email: trig.candidate_email || cand.email,
    position: trig.position || cand.applied_position || cand.position || "Vị trí chuyên môn",
    interview_time: trig.interview_time || cand.interview_time || "2026-10-18 09:30:00",
    interviewer: trig.interviewer || cand.interviewer_name || "Lê Hoàng Dev (Backend Lead)",
    meet_link: trig.meet_link || cand.meeting_link || "https://meet.google.com/rec-meet-vku",
    focus_topics: trig.focus_topics || "Kiến trúc hệ thống, Khả năng chịu tải",
    is_rejection: isRejection,
    prompt: isRejection
      ? `Soạn thư từ chối mang tính xây dựng cao (Constructive Growth Feedback) cho ứng viên ${cand.full_name || trig.candidate_name} vị trí ${cand.applied_position || trig.position}. Cảm ơn và chỉ ra 2 kỹ năng nên trau dồi để ứng tuyển lại trong tương lai.`
      : `Soạn thư mời phỏng vấn trang trọng kèm Bộ tài liệu chuẩn bị (Preparation Kit) cho ứng viên ${cand.full_name || trig.candidate_name} vị trí ${cand.applied_position || trig.position} vào lúc ${trig.interview_time || cand.interview_time} với Lead ${trig.interviewer || cand.interviewer_name}.`
  }
}];

return JSON.stringify({
  technical_readiness: ["Ôn tập kiến trúc phân tán & Microservices", "Chuẩn bị demo một dự án tiêu biểu"],
  interview_checklist: ["Kiểm tra webcam & mic trước 10 phút", "Tìm không gian yên tĩnh và đường truyền ổn định"]
});

return JSON.stringify({
  highlight: "Hồ sơ của bạn có nền tảng tư duy lập trình và học vấn tốt.",
  growth_recommendation: "Nếu bổ sung thêm kinh nghiệm triển khai Docker Container trên server thực tế, hồ sơ sẽ vô cùng cạnh tranh."
});

const d = $('4. Normalize Candidate Context').first().json;
const isRejection = d.is_rejection;

let subject = "";
let html_body = "";

if (isRejection) {
  subject = `[VKU Tech] Thông báo kết quả ứng tuyển vị trí ${d.position} - ${d.candidate_name}`;
  html_body = `
  <div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; border: 1px solid #e0e0e0; border-radius: 8px; padding: 24px;">
    <h2 style="color: #0d47a1; margin-top: 0;">VKU Tech Talent Acquisition</h2>
    <p>Xin chào <strong>${d.candidate_name}</strong>,</p>
    <p>Hội đồng tuyển dụng VKU Tech chân thành cảm ơn bạn đã dành thời gian và sự quan tâm đối với vị trí <strong>${d.position}</strong>.</p>
    <p>Sau khi xem xét kỹ lưỡng hồ sơ, chúng tôi rất tiếc phải thông báo hiện tại hồ sơ của bạn chưa hoàn toàn phù hợp với các tiêu chí ưu tiên của vị trí này.</p>
    <div style="background: #f4f6f8; border-left: 4px solid #1976d2; padding: 12px 16px; margin: 20px 0;">
      <h4 style="margin: 0 0 8px 0; color: #1976d2;">💡 Góc Nhìn Phát Triển Tự Động Từ AI Agent:</h4>
      <p style="margin: 0; font-size: 14px; color: #555;">Hồ sơ của bạn có tư duy kỹ thuật tốt. Nhóm tuyển dụng kiến nghị bạn tiếp tục trau dồi các dự án thực tế về Cloud & Docker để sẵn sàng cho các cơ hội tiếp theo tại công ty.</p>
    </div>
    <p>Thông tin của bạn đã được lưu trữ trong Talent Pool của chúng tôi và chúng tôi sẽ chủ động liên hệ lại khi có vị trí tương thích.</p>
    <p>Chúc bạn luôn kiên trì và gặt hái nhiều thành công trên con đường sự nghiệp!</p>
    <hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;">
    <p style="font-size: 13px; color: #777;">Trân trọng,<br><strong>Ban Tuyển Dụng & AI Agent Coordinator - VKU Tech</strong></p>
  </div>`;
} else {
  subject = `[VKU Tech] Thư mời phỏng vấn vị trí ${d.position} - ${d.candidate_name}`;
  html_body = `
  <div style="font-family: Arial, sans-serif; line-height: 1.6; color: #333; max-width: 600px; margin: 0 auto; border: 1px solid #e0e0e0; border-radius: 8px; padding: 24px;">
    <h2 style="color: #2e7d32; margin-top: 0;">🎉 Thư Mời Phỏng Vấn Chính Thức</h2>
    <p>Xin chào <strong>${d.candidate_name}</strong>,</p>
    <p>Chúc mừng bạn đã vượt qua vòng đánh giá hồ sơ xuất sắc cho vị trí <strong>${d.position}</strong> tại VKU Tech!</p>
    <div style="background: #f1f8e9; border: 1px solid #c8e6c9; border-radius: 6px; padding: 16px; margin: 20px 0;">
      <h3 style="margin-top: 0; color: #2e7d32;">Chi Tiết Buổi Phỏng Vấn Trực Tuyến:</h3>
      <ul style="margin: 0; padding-left: 20px;">
        <li><strong>Thời gian:</strong> <span style="color: #d32f2f; font-weight: bold;">${d.interview_time}</span></li>
        <li><strong>Chuyên gia phỏng vấn:</strong> ${d.interviewer}</li>
        <li><strong>Hình thức:</strong> Phỏng vấn trực tuyến qua Google Meet</li>
      </ul>
      <div style="text-align: center; margin-top: 16px;">
        <a href="${d.meet_link}" style="background: #1a73e8; color: #fff; padding: 12px 24px; text-decoration: none; border-radius: 4px; font-weight: bold; display: inline-block;">Tham Gia Phỏng Vấn (Google Meet)</a>
      </div>
    </div>
    <div style="background: #e8f0fe; border-left: 4px solid #1a73e8; padding: 12px 16px; margin: 20px 0;">
      <h4 style="margin: 0 0 6px 0; color: #1a73e8;">📚 Cẩm Nang Chuẩn Bị (AI Preparation Kit):</h4>
      <p style="margin: 0; font-size: 14px; color: #444;">Chủ đề trọng tâm: <em>${d.focus_topics}</em>. Bạn vui lòng chuẩn bị máy tính có kết nối ổn định và vào link trước 5 phút nhé.</p>
    </div>
    <p>Lịch hẹn này đã được hệ thống tự động đồng bộ lên Google Calendar của bạn.</p>
    <hr style="border: none; border-top: 1px solid #eee; margin: 20px 0;">
    <p style="font-size: 13px; color: #777;">Trân trọng,<br><strong>Ban Tuyển Dụng VKU Tech</strong></p>
  </div>`;
}

return [{
  json: {
    ...d,
    subject,
    html_body,
    is_rejection: isRejection
  }
}];

